package pggenerate

import "sync/atomic"

// upgradeHeights holds the function set by SetUpgradeHeights.
var upgradeHeights atomic.Pointer[func(chainID string) int64]

// SetUpgradeHeights sets the function that gives, for a chain ID, the first
// block height whose statements are generated by GenerateSQL. Below that
// height, a statement that may change state is generated by
// GenerateLegacySQL, so that blocks replay with the SQL they were executed
// with. Every node of a network must use the same heights, so the function
// is set once, before the node executes any block, by the application that
// embeds the engine. A height of math.MaxInt64 keeps a chain on the legacy
// generator, as does a nil function, which is the default. Read-only
// statements, which never change state, are always generated by GenerateSQL.
func SetUpgradeHeights(fn func(chainID string) int64) {
	if fn == nil {
		upgradeHeights.Store(nil)
		return
	}
	upgradeHeights.Store(&fn)
}

// LegacyAt reports whether a statement that may change state, executed in the
// block at the given height of the chain chainID, is generated by
// GenerateLegacySQL. A statement that is executed outside a block, with no
// chain ID, is.
func LegacyAt(chainID string, height int64) bool {
	if chainID == "" {
		return true
	}
	fn := upgradeHeights.Load()
	if fn == nil {
		return true
	}
	return height < (*fn)(chainID)
}
